#!/usr/bin/env python3# -*- coding: utf-8 -*-"""2. People in Norway by region and age in 2022@author: oblig0_289412"""from pathlib import Pathimport pandas as pdimport reimport matplotlib.pyplot as pltdef get_path(filepath):    path = Path(filepath)    if not path.exists():        raise FileNotFoundError(f"File not found: {filepath}")    return pathdef read_file(filepath):    path = get_path(filepath)    with open(path)as f:        for _ in range(5):            print(next(f).strip())    return pd.read_csv(path, delimiter=";") filepath = Path("data") / "nor_population2022.csv"data = read_file(filepath)print(data.columns)def clean_population_data(filepath):    path = get_path(filepath)    data = pd.read_csv(        path,        delimiter=";",        converters={"alder": lambda x: int(re.search(r"(\d+) (ar)", x).group(1))},).drop(["ar", "xxx"], axis="columns")    return datadata_clean = clean_population_data(filepath)print (data_clean)def population_in_different_regions(data):    region = data.groupby("region")["count"].sum().plot()    plt.xticks(rotation=45);    return regionpopulation_in_different_regions(data)plt.show()def breakdown_distribution():    fig, ax = plt.subplots()    data.pivot_table("count", index="alder", columns=["region"]).plot(ax=ax)    ax.legend(bbox_to_anchor=(1.05, 0.5))    return fig, axbreakdown_distribution()plt.show()